# One regression run for the whole tool.  python3 tools/regress.py [URL]   (needs the site served, e.g. python3 -m http.server 8765 in the site folder;
# set HTTPS_PROXY if the browser needs a proxy to reach the API; CHROME_PATH for a non-default Chrome)
import os, sys, json, time
from playwright.sync_api import sync_playwright
URL = (sys.argv[1] if len(sys.argv) > 1 else 'http://127.0.0.1:8765/index.html').split('#')[0]
fails, ok, errors = [], [], []
def check(name, cond, detail=''):
    (ok if cond else fails).append(name); print(('PASS ' if cond else 'FAIL ') + name + ('' if cond else '  ' + str(detail)), flush=True)
BOOT = "() => getComputedStyle(document.getElementById('boot')).display === 'none'"
CHART = "() => __hx.chart && __hx.wv.rows.length"
with sync_playwright() as p:
    proxy = {'server': os.environ['HTTPS_PROXY'], 'bypass': '127.0.0.1,localhost'} if os.environ.get('HTTPS_PROXY') else None
    b = p.chromium.launch(executable_path=os.environ.get('CHROME_PATH', '/usr/bin/google-chrome'), headless=True, proxy=proxy, args=['--no-sandbox'])
    ctx = b.new_context(viewport={'width': 1500, 'height': 950}, accept_downloads=True)
    def open_(hash_=''):
        pg = ctx.new_page(); pg.on('pageerror', lambda e: errors.append(str(e))); pg.goto(URL + hash_); pg.wait_for_function(BOOT, timeout=900000); return pg
    # 1. first visit (snapshot if present) and revisit
    t0 = time.time(); pg = open_(); first_s = time.time() - t0
    info = pg.evaluate("() => ({mode: __hx.boot.mode, n: __hx.rawN, max: __hx.boot.maxDate})")
    check('first visit loads all readings', info['n'] > 850000, info)
    check('first visit mode is snapshot+delta or full', info['mode'] in ('snapshot+delta', 'full'), info); print('  first visit', round(first_s, 1), 's', info)
    pg.wait_for_timeout(3000); pg.close(); pg = open_('#hydrographs?a=county%7CBernalillo')
    check('revisit uses the saved copy', pg.evaluate("() => __hx.boot.mode") == 'cache+delta')
    # 2. link restore selects the area
    pg.wait_for_function(CHART, timeout=180000); pg.wait_for_timeout(1500)
    s = pg.evaluate("() => ({area: __hx.state.areaSelection && __hx.state.areaSelection.label, screen: __hx.screen, n: __hx.wv.rows.length, all: __hx.wv.all.length})")
    check('link restores county + screen', s['area'] == 'County: Bernalillo' and s['screen'] == 'charts' and s['n'] > 0, s)
    # 3. Show control
    pg.click('#sa-values [data-v=first]'); pg.wait_for_timeout(1200)
    check('change since first: every line starts at 0', pg.evaluate("() => __hx.wv.rows.every(w => w.pts[0].y === 0 || w.pts.find(p => !p.flag).y === 0)"))
    pg.click('#sa-values [data-v=as]'); pg.click('#wv-step [data-step=year]'); pg.wait_for_timeout(1200)
    check('annual step draws', pg.evaluate("() => __hx.wv.stepUsed") == 'year')
    pg.click('#wv-step [data-step=raw]'); pg.wait_for_timeout(1200)
    # 4. period, link out, link back
    pg.evaluate("() => { const w = document.getElementById('yw-min'); w.value = 2000; w.dispatchEvent(new Event('input')); w.dispatchEvent(new Event('change')); }"); pg.wait_for_timeout(1500)
    h = pg.evaluate("() => (document.getElementById('btn-copylink').click(), 0) || location.hash"); pg.wait_for_timeout(600); h = pg.evaluate("() => location.hash")
    check('address carries the period', 'y0=2000' in h, h)
    pg2 = open_(h); pg2.wait_for_function(CHART, timeout=180000); pg2.wait_for_timeout(1500)
    check('link restores the period', pg2.evaluate("() => __hx.state.yearWindow.min") == 2000)
    pg2.close()
    # 5. trend table
    pg.evaluate("() => { const w = document.getElementById('yw-min'); w.value = ''; w.dispatchEvent(new Event('input')); w.dispatchEvent(new Event('change')); }"); pg.wait_for_timeout(1500)
    pg.click('#btn-trends'); pg.wait_for_timeout(600)
    check('trend table lists wells', pg.evaluate("() => document.querySelectorAll('#trend-body tr[data-s]').length") > 100)
    with pg.expect_download() as d: pg.click('#trend-csv')
    check('trend csv downloads', len(open(d.value.path()).read().splitlines()) > 100)
    pg.click('#trend-close')
    # 6. composite unchanged
    pg.click('#view-seg button[data-view=composite]'); pg.wait_for_timeout(9000)
    st = pg.evaluate("() => ['stat-nqual', 'stat-npoints', 'stat-meanchg', 'stat-medchg'].map(id => document.getElementById(id).textContent)")
    check('composite for Bernalillo still builds (753 wells, 74 years)', st[0].replace(',', '').startswith('753') and '74' in st[1], st)
    r5 = pg.evaluate("() => { __hx.otp.bin = 5; const r = __hx.computeComposite(); __hx.otp.bin = 1; return r && r.xvals ? {n: r.xvals.length, ok: r.xvals.every(x => (x - 1982) % 5 === 0)} : null; }")
    check('5-year time step puts the composite on 1980-84 ... bin middles', bool(r5) and r5['ok'] and r5['n'] > 5, r5)
    pg.click('#view-seg button[data-view=wells]'); pg.wait_for_timeout(1500)
    # 7. user readings
    open('/tmp/regress_user.csv', 'w').write('source,id,date,depth_to_water\nUSGS-NWIS,USGS-350256106390801,1930-03-01,10.5\n')
    pg.set_input_files('#import-file', '/tmp/regress_user.csv'); pg.wait_for_timeout(3000)
    check('user readings are added', '1 reading' in pg.inner_text('#import-status') or '1 reading(s) added' in pg.inner_text('#import-status'), pg.inner_text('#import-status'))
    # 8. record-reach filter drops wells but keeps their readings
    pg.evaluate("() => { __hx.state.filters.yearMin = null; }")
    n0 = pg.evaluate("() => __hx.wv.all.length")
    pg.evaluate("() => { const e = document.getElementById('year-min'); e.value = '2020'; e.dispatchEvent(new Event('input', {bubbles: true})); }"); pg.wait_for_timeout(2500)
    n1 = pg.evaluate("() => __hx.wv.all.length")
    check('last reading in or after 2020 drops wells', 0 < n1 < n0, (n0, n1))
    early = pg.evaluate("() => __hx.wv.rows.some(w => w.pts.some(p => p.year < 2020))")
    check('kept wells keep readings from before 2020', early)
    pg.evaluate("() => { const e = document.getElementById('year-min'); e.value = ''; e.dispatchEvent(new Event('input', {bubbles: true})); }"); pg.wait_for_timeout(2000)
    # 9. compare periods
    pg.click('#btn-compare'); pg.wait_for_function("() => document.getElementById('cmp-body').children.length > 0", timeout=120000)
    check('compare periods fills the table', pg.evaluate("() => document.getElementById('cmp-body').children.length") > 0)
    check('compare summary and chart present', pg.evaluate("() => !!document.querySelector('#cmp-summary tr.cmp-key') && !!document.getElementById('cmp-hist')"))
    a = pg.evaluate("() => __hx.state && 1")
    with pg.expect_download() as dl: pg.click('#cmp-csv')
    check('compare CSV downloads', dl.value.suggested_filename.endswith('.csv'), dl.value.suggested_filename)
    pg.evaluate("() => document.getElementById('btn-copylink').click()"); pg.wait_for_timeout(600); hc = pg.evaluate("() => location.hash")
    pg.click('#cmp-close')
    pg3 = open_(hc); pg3.wait_for_function("() => !document.getElementById('cmp-modal').classList.contains('hidden') && document.getElementById('cmp-body').children.length > 0", timeout=240000)
    check('link reopens Compare periods with the same periods', 'ca=' in hc and pg3.evaluate("() => document.getElementById('cmp-a0').value") == hc.split('ca=')[1].split('-')[0], hc)
    pg3.close()
    # 10. Myers (2022) replication: the published well lists through the tool's readings (tools/myers-2022-groups.json)
    G = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'myers-2022-groups.json')))
    res = pg.evaluate("(G) => G.map(g => __hx.myersGroup(g.usgs_site_numbers, g.start_bin, g.end_bin))", G['groups'])
    drift, near = [], 0
    for g, r in zip(G['groups'], res):
        bl = g['tool_baseline']
        if r['qualifying'] != bl['qualifying'] or abs(r['meanChange'] - bl['mean_depth_change_ft']) > 0.3 or abs(r['medianChange'] - bl['median_depth_change_ft']) > 0.3:
            drift.append((g['name'][:30], r['qualifying'], r['meanChange'], r['medianChange'], bl))
        if abs(r['meanChange'] + g['published_wl_change_ft']['mean']) <= 1.5: near += 1
    check('Myers 2022 replication unchanged (12 groups: qualifying wells, mean and median change within 0.3 ft)', not drift, drift)
    check('Myers 2022: at least 9 of 12 group means within 1.5 ft of the published change', near >= 9, near)
    # 11. new tools: spread band, well influence, small multiples, period-trend colours, data issues, project file, report
    pg2 = open_('#hydrographs?a=county%7CSierra&v=c'); pg2.wait_for_function("() => __hx.chart && document.getElementById('stat-nqual').textContent !== '–'", timeout=240000); pg2.wait_for_timeout(2500)
    pg2.click('#toggle-iqr', force=True) if pg2.is_visible('#toggle-iqr') else pg2.evaluate("() => { const e = document.getElementById('toggle-iqr'); e.checked = true; e.dispatchEvent(new Event('change')); }")
    pg2.wait_for_timeout(2500)
    check('spread band (IQR) draws around the median', pg2.evaluate("() => !!(window._lastIqr && window._lastIqr.lo.some(v => v != null) && __hx.chart.data.datasets.some(d => d._iqr))"))
    pg2.click('#btn-influence'); pg2.wait_for_function("() => document.getElementById('inf-body').children.length > 0 && !/Working/.test(document.getElementById('inf-sum').textContent)", timeout=300000)
    nr = pg2.evaluate("() => document.querySelectorAll('#inf-body tr[data-s]').length"); nq = pg2.evaluate("() => parseInt(document.getElementById('stat-nqual').textContent.replace(/,/g, ''))")
    check('well influence ranks every well in the composite', nr == nq, (nr, nq))
    with pg2.expect_download() as dl: pg2.click('#inf-csv')
    check('well influence CSV downloads', len(open(dl.value.path()).read().splitlines()) == nq + 1)
    pg2.click('#inf-modal .hx-close')
    pg2.click('#btn-smallmult-c'); pg2.wait_for_timeout(2500)
    check('small multiples draws one tile per well', pg2.evaluate("() => document.querySelectorAll('#sm-grid .sm-tile canvas').length") >= min(24, nq))
    pg2.click('#sm-modal .hx-close')
    pg2.evaluate("() => { const e = document.getElementById('colorby-select'); e.value = 'ptrend'; e.dispatchEvent(new Event('change')); }"); pg2.wait_for_timeout(1500)
    check('map colours by the trend over the period', pg2.evaluate("() => document.getElementById('legend-body').textContent.includes('Theil') && /\\d/.test(document.getElementById('legend-body').textContent)"))
    # untick one source so the project carries a list filter that the area restore would otherwise re-tick
    pg2.evaluate("() => { const cb = [...document.querySelectorAll('#source-list input[data-src]:checked')].find(c => c.closest('label').textContent.includes('NMBGMR')); cb.checked = false; cb.dispatchEvent(new Event('change')); }")
    pg2.wait_for_timeout(3000); nq = pg2.evaluate("() => parseInt(document.getElementById('stat-nqual').textContent.replace(/,/g, ''))")
    proj = pg2.evaluate("async () => { const p = await __hx.projBuild(); return p; }")
    check('project file holds area, settings and filters', proj['kind'] == 'hydrograph-project' and proj['link'].get('a', '').startswith('county|') and len(proj['filters']['sources']) >= 1 and proj['otp']['method'] == 'fe', proj.get('link'))
    rep = pg2.evaluate("async () => await __hx.reportBuild()")
    check('area report builds (map, chart, statistics)', rep['wells'] == nq and pg2.evaluate("() => document.querySelectorAll('#hx-report img').length") == 2, rep)
    pg2.close()
    # 12. pumping flags, OSE production wells, vertical datum, data-issues report (Sierra County)
    pg4 = open_('#hydrographs?a=county%7CSierra'); pg4.wait_for_function(CHART, timeout=240000); pg4.wait_for_timeout(1500)
    pg4.evaluate("() => { const e = document.getElementById('rq-pump'); e.checked = true; e.dispatchEvent(new Event('change')); }"); pg4.wait_for_timeout(4000)
    pm = pg4.evaluate("() => ({n: __hx.pump.n, wells: __hx.pump.wells, on: __hx.state.readQ.pumpHeur})")
    check('likely pumped readings are found and left out', pm['on'] and pm['n'] > 100 and pm['wells'] > 10, pm)
    pg4.evaluate("() => { const e = document.getElementById('prod-filter'); e.value = 'noProd'; e.dispatchEvent(new Event('change')); }")
    pg4.wait_for_function("() => __hx.prod.checked.size > 0 && !__hx.prod.busy", timeout=300000); pg4.wait_for_timeout(2500)
    pr = pg4.evaluate("() => { const P = __hx.prod, m = [...P.by.values()]; return {checked: P.checked.size, matched: m.length, prod: m.filter(x => x.prod).length, failed: P.failed, active: __hx.state.activeSet.size}; }")
    check('OSE well records are matched and production wells left out', pr['checked'] > 100 and pr['matched'] > 0 and pr['failed'] == 0, pr)
    pg4.evaluate("() => document.getElementById('btn-mode-elevation').click()"); pg4.wait_for_function("() => __hx.datum.loaded", timeout=120000); pg4.wait_for_timeout(2000)
    dm = pg4.evaluate("() => ({ngvd: __hx.datum.ngvd, shifted: __hx.datum.shifted})")
    check('NGVD 29 site elevations are converted to NAVD 88', dm['ngvd'] > 10000 and dm['shifted'] == dm['ngvd'], dm)
    iss = pg4.evaluate("async () => { const r = await __hx.issuesBuild(null); const by = {}; r.rows.forEach(x => by[x[0]] = (by[x[0]] || 0) + 1); return by; }")
    check('data-issues report finds the known kinds of problems', all(iss.get(k, 0) > 0 for k in ['link_wells_too_far_apart', 'linked_wells_different_depths', 'reading_dated_in_future', 'likely_data_entry_error', 'likely_pumped_reading_not_qualified']), iss)
    pg4.close()
    pg3 = open_('#hydrographs')
    pg3.evaluate("(p) => __hx.projOpen(p)", proj); pg3.wait_for_function("() => __hx.state.areaSelection && document.getElementById('stat-nqual').textContent !== '–'", timeout=240000); pg3.wait_for_timeout(2000)
    n3 = pg3.evaluate("() => parseInt(document.getElementById('stat-nqual').textContent.replace(/,/g, ''))")
    check('project file reopens the same composite (area, unticked source, spread band)', n3 == nq and pg3.evaluate("() => __hx.state.showIqr") and pg3.evaluate("(n) => __hx.state.filters.sources.size", None) == len(proj['filters']['sources']), (n3, nq))
    pg3.close()
    # 13. regional water table, screened intervals, aquifer-outline area units, NMBGMR preset, decade step (Chaves County)
    sel = "([i, v]) => { const e = document.querySelector(i); e.value = v; e.dispatchEvent(new Event('change')); }"
    pg5 = open_('#hydrographs?a=county%7CChaves'); pg5.wait_for_function(CHART, timeout=240000); pg5.wait_for_function("() => __hx.wt.grid", timeout=120000); pg5.wait_for_timeout(2000)
    wt = pg5.evaluate("() => { const R = __hx.wt.res, a = []; for(let s = 0; s < R.length; s++) if(isFinite(R[s])) a.push(R[s]); a.sort((x, y) => x - y); return {n: a.length, med: a[a.length >> 1]}; }")
    check('regional water table: residual for 35,000+ wells, median within ±15 ft', wt['n'] > 35000 and abs(wt['med']) < 15, wt)
    n0 = pg5.evaluate("() => __hx.state.activeSet.size")
    pg5.evaluate(sel, ['#wt-filter', 'near']); pg5.wait_for_timeout(2500); n1 = pg5.evaluate("() => __hx.state.activeSet.size")
    pg5.evaluate(sel, ['#wt-filter', 'above']); pg5.wait_for_timeout(2500); n2 = pg5.evaluate("() => __hx.state.activeSet.size")
    pg5.evaluate(sel, ['#wt-filter', 'below']); pg5.wait_for_timeout(2500); n3b = pg5.evaluate("() => __hx.state.activeSet.size")
    pg5.evaluate(sel, ['#wt-filter', 'all']); pg5.wait_for_timeout(2500)
    check('water-table filter splits the selection (near + above + below <= all)', 0 < n1 < n0 and n2 > 0 and n3b > 0 and n1 + n2 + n3b <= n0, [n0, n1, n2, n3b])
    pg5.evaluate(sel, ['#colorby-select', 'wtres']); pg5.wait_for_timeout(1200)
    check('water-table map colour has a legend', 'mapped water table' in pg5.inner_text('#legend-body').lower())
    pg5.evaluate(sel, ['#colorby-select', 'source'])
    pg5.click('#view-seg button[data-view=composite]'); pg5.wait_for_timeout(8000)
    pg5.evaluate(sel, ['#group-mode', 'wtres']); pg5.wait_for_timeout(6000)
    gi = pg5.inner_text('#group-info'); pg5.evaluate(sel, ['#group-mode', 'off']); pg5.wait_for_timeout(1500)
    check('group by head against the regional water table draws groups', ' ft' in gi and '(' in gi, gi[:200])
    pg5.evaluate(sel, ['#ot-unitkind', 'huc10']); pg5.evaluate(sel, ['#ot-method', 'units']); pg5.wait_for_timeout(15000)
    hu = pg5.evaluate("() => { const r = __hx.computeComposite(); return r && r.unitsInfo ? r.unitsInfo : null; }")
    check('HUC-10 area units load their boundaries from kriged/ (not pending)', bool(hu) and not hu.get('pending') and hu.get('units', 0) >= 2, hu)
    pg5.evaluate(sel, ['#ot-method', 'fe']); pg5.wait_for_timeout(2000)
    pg5.evaluate(sel, ['#ot-unitkind', 'aquifer']); pg5.evaluate(sel, ['#ot-method', 'units']); pg5.wait_for_timeout(9000)
    au = pg5.evaluate("() => { const r = __hx.computeComposite(); return r && r.unitsInfo ? Object.assign({n: r.xvals.length}, r.unitsInfo) : null; }")
    check('area units by aquifer outline build (overlaps as own units)', bool(au) and au.get('kind') == 'aquifer' and au['units'] >= 2 and au['n'] > 20, au)
    ar = pg5.evaluate("() => { const m = __hx.aqUnitAreas(__hx.computeComposite().perWell.map(pw => { const x = new Map(); x._s = pw.site; return x; })); let t = 0; m.forEach(v => t += v); return t; }")
    check('aquifer unit areas add up to about the county (Chaves 15,700 km2)', 13000 < ar < 18500, ar)
    pg5.evaluate(sel, ['#ot-method', 'fe']); pg5.wait_for_timeout(3000)
    pg5.evaluate("() => document.getElementById('btn-nmbgmr-preset').click()"); pg5.wait_for_timeout(9000)
    pr5 = pg5.evaluate("() => { const r = __hx.computeComposite(); return {bin: __hx.state.otp.bin, ms: __hx.state.season.monthStart, me: __hx.state.season.monthEnd, nod: __hx.state.readQ.noDisturbed, x: r ? r.xvals : []}; }")
    check('NMBGMR preset: Nov-Feb, no pumping readings, decades plotted at 1955, 1965 ...', pr5['bin'] == 10 and pr5['ms'] == 11 and pr5['me'] == 2 and pr5['nod'] and len(pr5['x']) >= 4 and all(x % 10 == 5 for x in pr5['x']), pr5)
    iss5 = pg5.evaluate("async () => { const r = await __hx.issuesBuild(null); return r.rows.filter(x => x[0] === 'far_from_regional_water_table').length; }")
    check('data issues include wells far off the regional water table and their neighbours (500-2,000 statewide)', 500 < iss5 < 2000, iss5)
    pg5.evaluate("() => { const b = document.getElementById('btn-prod-check'); b.click(); }"); pg5.wait_for_function("() => __hx.prod.checked.size > 100 && !__hx.prod.busy", timeout=300000)
    sc = pg5.evaluate("() => { let m = 0, p = 0; __hx.prod.by.forEach(v => { m++; if(v.ptop > 0) p++; }); return {m, p}; }")
    check('OSE well records carry screened intervals', sc['m'] > 0 and sc['p'] > 0, sc)
    # 15. well detail drawer and card: construction from OSE and NMBGMR, schematic, every field (EB-011, Santa Fe County)
    s11 = pg5.evaluate("() => __hx.siteOf('NMBGMR~EB-011')")
    c11 = pg5.evaluate("(s) => __hx.wdConstruction(s)", s11)
    check('well detail: EB-011 gets its OSE screen (200-260 ft) and NMBGMR casing (5.04 in to 260 ft)', bool(c11.get('screens')) and c11['screens']['v'] == [{'top': 200, 'bot': 260}] and c11.get('casingDiam', {}).get('v') == 5.04 and c11.get('casingDepth', {}).get('v') == 260, c11)
    pg5.evaluate("(s) => __hx.wdOpen(s)", s11); pg5.wait_for_function("() => !document.querySelector('#wd-main .wd-loading')", timeout=120000)
    wd = pg5.evaluate("() => [document.body.classList.contains('wd-open'), document.querySelectorAll('#wd-main svg.wd-schem rect.wd-screen').length, document.querySelectorAll('#wd-main details.wd-all').length, /Owners|own_lname|addr1/.test(document.getElementById('wd-main').innerHTML)]")
    check('well detail drawer: schematic with the screen, every-field tables, no owner names or addresses', wd[0] and wd[1] == 1 and wd[2] >= 3 and not wd[3], wd)
    pg5.evaluate("() => __hx.wdClose()")
    pg5.evaluate("(s) => __hx.openCard(s)", s11); pg5.wait_for_function("() => document.getElementById('sw-detail') && !document.querySelector('#sw-detail .wd-loading')", timeout=120000)
    check('single-well card shows the same schematic', pg5.evaluate("() => document.querySelectorAll('#sw-detail svg.wd-schem').length") == 1)
    pg5.evaluate("() => document.getElementById('sw-close').click()")
    # 16. Weaver API address, and the newer Ocotillo collections (monitoring plans, water column, chemistry, isotopes, layers)
    check('readings come from the Weaver API address', 'weaver-api.newmexicowaterdata.org' in pg5.evaluate("() => performance.getEntriesByType('resource').map(e => e.name).filter(u => u.includes('/collections/nm_')).join(' ')"))
    s01 = pg5.evaluate("() => __hx.siteOf('NMBGMR~EB-001')")
    pg5.evaluate("(s) => __hx.wdOpen(s)", s01); pg5.wait_for_function("() => !document.querySelector('#wd-main .wd-loading')", timeout=120000)
    t01 = pg5.evaluate("() => document.getElementById('wd-main').innerText")
    check('well detail (EB-001): NMBGMR monitoring plan, water column, elevation method and major chemistry', all(k in t01 for k in ['La Cienega', 'Water column (NMBGMR)', 'Elevation method', 'Major ions']), t01[:300])
    s08 = pg5.evaluate("() => __hx.siteOf('NMBGMR~AR-0008')")
    pg5.evaluate("(s) => __hx.wdOpen(s)", s08); pg5.wait_for_function("() => !document.querySelector('#wd-main .wd-loading')", timeout=120000)
    t08 = pg5.evaluate("() => document.getElementById('wd-main').innerText")
    check('well detail (AR-0008): isotopes with a 14C apparent age', 'δ¹⁸O' in t08 and 'apparent age' in t08)
    n08 = pg5.evaluate("() => { const e = document.querySelector('#wd-main .wd-notes'); return e ? e.innerText : ''; }")
    check('well detail (AR-0008): "Reading this" notes with sources (short record, water column, deuterium excess, uncorrected 14C)', all(k in n08 for k in ['Taylor & Alley 2001', 'Jasechko & Perrone 2021', 'Deuterium excess', 'Plummer & Glynn 2013']) and 'mapped water table' not in n08, n08[:400])
    pg5.evaluate("() => __hx.wdClose()")
    pg5.evaluate("() => __hx.actLoad()"); pg5.wait_for_timeout(1500)
    act = pg5.evaluate("() => ({n: __hx.act.by ? __hx.act.by.size : 0, plans: __hx.act.groups.length})")
    check('NMBGMR actively monitored wells and their plans load (300+ wells, 10+ plans)', act['n'] > 300 and act['plans'] >= 10, act)
    lay = pg5.evaluate("async () => { const o = {}; for(const k of ['springs', 'amp', 'aem']) o[k] = (await __hx.ocoLayer(k)).getLayers().length; return o; }")
    check('NMBGMR map layers load (springs, project areas, AEM areas)', lay['springs'] > 500 and lay['amp'] > 20 and lay['aem'] >= 1, lay)
    # 14. State Engineer Technical Report 34: published 1965-66 changes of the observation wells, area by area (tools/tr34-1966-wells.json)
    H = json.load(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tr34-1966-wells.json')))
    hr = pg5.evaluate("(G) => G.map(g => __hx.histGroup(g.keys, 1965, 1966, g.published_dates_1966))", H['groups'])
    worst_mean = max(abs(-r['meanChange'] - g['published_mean_change_1965_1966_ft']) for r, g in zip(hr, H['groups']) if r['meanChange'] is not None)
    worst_fit = max(abs(-r['fitChange'] - g['published_mean_change_1965_1966_ft']) for r, g in zip(hr, H['groups']) if r['fitChange'] is not None)
    found = sum(r['found'] for r in hr); want = sum(g['n'] for g in H['groups'])
    check('TR 34 wells are all in the API', found == want, [found, want])
    check('TR 34: API readings on the published dates reproduce the published 1965-66 area means (within 0.1 ft)', worst_mean <= 0.1, [(g['area'], g['published_mean_change_1965_1966_ft'], r['meanChange'] and round(-r['meanChange'], 2)) for r, g in zip(hr, H['groups'])])
    print('  info: matched-wells fit 1960-71, change 1965-66 vs published mean:', [(g['area'], g['published_mean_change_1965_1966_ft'], r['fitChange'] and round(-r['fitChange'], 2)) for r, g in zip(hr, H['groups'])])
    # 17. published numbers for the area and the area summary (Chaves County: Myers table 14, TR 34 Roswell areas, Rinehart & Mamer 2017)
    pg5.wait_for_timeout(3000)
    pub = pg5.evaluate("""() => __hx.pubRender().map(r => ({src: r.src, title: r.title, pub: r.pub, tool: r.tool}))""")
    srcs = [r['src'] for r in pub]
    check('published numbers for Chaves County: Myers 2022 Roswell Basin, TR 34 Roswell areas, Rinehart & Mamer 2017 Roswell', any('table 14' in r['title'] for r in pub) and sum(1 for r in pub if r['src'] == 'tr34' and 'Roswell' in r['title']) == 2 and 'r17' in srcs, [r['title'] for r in pub])
    num = lambda t: float(t.replace('\u2212', '-').split(': ')[-1].split(' ')[0]) if t else None
    tr = [(r['title'], float(r['pub'].split(' ')[0]), num(r['tool'])) for r in pub if r['src'] == 'tr34']
    check('published numbers: TR 34 areas recomputed within 0.1 ft of the published means', tr and all(abs(a - b) <= 0.1 for _, a, b in tr), tr)
    pc = pg5.evaluate("() => { const d = document.getElementById('pub-strip'); return {open: d.open, cards: d.querySelectorAll('.pub-row').length, det: d.querySelectorAll('.pub-row .pub-det li').length, spark: d.querySelectorAll('.pub-spark svg').length, links: d.querySelectorAll('.pub-row a[href]').length}; }")
    check('published-number cards are open by default, with details, a chart for Myers and report links', pc['open'] and pc['cards'] == len(pub) and pc['det'] >= 3 * pc['cards'] and pc['spark'] >= 1 and pc['links'] >= 2, pc)
    summ = pg5.evaluate("async () => { const r = await __hx.areaSummary(); return r ? {text: r.text, refs: r.refs, change: r.numbers.change, pub: r.numbers.published.length} : null; }")
    check('area summary: composite change, sources, published numbers, no use of the mapped water table', bool(summ) and summ['change'] and 'Taylor & Alley 2001' in summ['refs'] and summ['pub'] >= 3 and summ['text'].count('mapped water table') == 1 and summ['text'].endswith('The mapped water table is not used in this summary.'), summ and summ['text'][:300])
    # 18. context under the composite: drought, metered pumping, public water systems (context-data.bin)
    pg5.evaluate("() => document.querySelector('#view-seg [data-view=composite]').click()"); pg5.wait_for_timeout(5000)
    cx = pg5.evaluate("""async () => { await __hx.ctxRender(); const c = __hx.ctx; return {last: c.data && c.data.usdm.last, drought: c.drought && c.drought.label, dv: c.drought ? c.drought.vals.filter(v => v).length : 0,
      pump: c.pump && c.pump.n, pumpYears: c.pump && c.pump.years ? c.pump.years.length : 0, pws: c.pws && c.pws.systems.length, pop: c.pws && c.pws.pop,
      vis: [...document.querySelectorAll('#ctx-strips .ctx-row')].map(e => getComputedStyle(e).display)}; }""")
    check('context (10-year steps here, so 3 decades since 2000): Drought Monitor for Chaves County, metered pumping and public water systems in the county', cx['last'] and cx['last'] >= '2026-01-01' and cx['drought'] == 'Chaves County' and cx['dv'] >= 3 and cx['pump'] and cx['pump'] > 50 and cx['pumpYears'] >= 20 and cx['pws'] and cx['pws'] >= 5 and cx['vis'] == ['block', 'block'], cx)
    cs = pg5.evaluate("async () => { const r = await __hx.areaSummary(); return r ? r.sentences.join(' ') : ''; }")
    check('area summary includes drought, metered pumping, public water systems and NMED static levels', all(k in cs for k in ['U.S. Drought Monitor', 'OSE meter readings', 'public water system', 'NMED recorded a one-time static water level']), cs[-700:])
    sw = pg5.evaluate("async () => { const l = __hx.swlList(); const g = await __hx.swlLayer(); return {n: l.length, flagged: l.filter(x => x.flags.length).length, markers: g.getLayers().length, box: !!document.getElementById('layer-nmed-swl')}; }")
    check('NMED static water levels: 1,500+ supply wells, map layer and checkbox, a few flagged', sw['n'] >= 1500 and sw['markers'] == sw['n'] and sw['box'] and 0 < sw['flagged'] < 50, sw)
    gw = pg5.evaluate("""() => { const G = __hx.gwfs, ri = G.regions.findIndex(r => r.name === 'Middle Rio Grande'); __hx.gwfsSelectRegion(ri);
      const a = {label: __hx.state.areaSelection.label, n: __hx.state.activeSet.size, subs: [...document.querySelectorAll('#gwfssub-select option')].length - 1};
      __hx.gwfsSelectSub(G.subs.findIndex(x => x.name === 'Albuquerque')); const b = {label: __hx.state.areaSelection.label, n: __hx.state.activeSet.size, region: document.getElementById('gwfs-select').selectedOptions[0].textContent};
      return {regions: G.regions.length, subsAll: G.subs.length, a, b}; }""")
    check('GWFS regions (10) and sub-regions (20): Middle Rio Grande lists its 4 sub-regions; Albuquerque is a smaller selection inside it', gw['regions'] == 10 and gw['subsAll'] == 20 and gw['a']['label'] == 'GWFS region: Middle Rio Grande' and gw['a']['subs'] == 4 and gw['b']['label'] == 'GWFS sub-region: Albuquerque' and 0 < gw['b']['n'] < gw['a']['n'] and gw['b']['region'] == 'Middle Rio Grande', gw)
    pg5.evaluate("() => { const e = document.getElementById('county-select'); const o = [...e.options].find(x => x.textContent.trim() === 'Chaves'); e.value = o.value; e.dispatchEvent(new Event('change')); }"); pg5.wait_for_timeout(3000)
    rep = pg5.evaluate("async () => { const r = await __hx.reportBuild(); return {pub: r.published, summ: !!r.summary, h: [...document.querySelectorAll('#hx-report h2')].map(e => e.textContent)}; }")
    check('area report has the area summary and the published-numbers table', rep['summ'] and rep['pub'] >= 3 and 'Area summary' in rep['h'] and 'Published numbers for this area' in rep['h'], rep)
    pg5.close()
    b.close()
check('no page errors', not errors, errors)
print(f'\n{len(ok)} passed, {len(fails)} failed'); sys.exit(1 if fails else 0)
